'use client'
import { useState, type CSSProperties } from 'react'
import { type DayPoint, compactNumber, dayMarks, formatDay, formatNumber, niceTicks } from '@/lib/chart'
import { cn } from '@/react/lib/cn'

// A White bar per day on the Black ground. The axis starts at 0 and ends on a round number in about four steps; grid
// lines are #363636 hairlines; axis figures are DM Sans 12px muted in tabular figures. A day with any activity keeps a
// visible bar. Pointing at a bar names its day and value in the caption and quiets the others to #4D4D4D. The bars
// rise from the axis once (360ms, ease-out, staggered over 120ms), then only their color changes; with reduced motion
// they are simply there. `focus`: bars lit from outside, the rest quiet; `note`: what the caption says meanwhile.
export interface BarChartProps {
  /** One value per day: [{ day (ISO), value }]. */
  points: DayPoint[]
  /** The caption: what the bars count. */
  label: string
  /** The bars' height in px. */
  height?: number
  /** Indexes lit from outside, the rest quiet. */
  focus?: number[]
  /** What the caption says while nothing is pointed at. */
  note?: string
}

export function BarChart({ points, label, height = 160, focus, note }: BarChartProps) {
  const ticks = niceTicks(points.map(p => p.value))
  const top = ticks[ticks.length - 1]!
  const marks = dayMarks(points)
  const [hover, setHover] = useState<number | null>(null)
  const shown = hover === null ? null : points[hover] ?? null
  const peak = formatNumber(Math.max(0, ...points.map(p => p.value)))
  return (
    <figure data-ds="bar-chart" className="flex min-w-0 flex-col gap-3">
      <style href="ds-bar-chart" precedence="ds">{css}</style>
      <figcaption className="flex h-5 items-baseline justify-between gap-4">
        <span className="type-label text-fg-muted">{label}</span>
        {shown
          ? <span className="type-caption text-fg-muted tabular-nums">{`${formatDay(shown.day, true)} `}<span className="font-medium text-fg">{formatNumber(shown.value)}</span></span>
          : note ? <span className="type-caption text-fg-muted">{note}</span> : null}
      </figcaption>
      {!points.length
        ? <p className="flex items-center justify-center type-ui text-fg-muted" style={{ height: `${height}px` }}>No activity yet.</p>
        : (
            <div className="grid grid-cols-[40px_minmax(0,1fr)] gap-x-2">
              <div className="relative" style={{ height: `${height}px` }} aria-hidden="true">
                {ticks.map(t => <span key={t} className="absolute right-0 -translate-y-1/2 type-caption text-fg-muted tabular-nums" style={{ top: `${(1 - t / top) * 100}%` }}>{compactNumber(t)}</span>)}
              </div>
              <div className="relative" style={{ height: `${height}px` }} role="img" aria-label={`${label}: ${points.length} days, peak ${peak}`} onPointerLeave={() => setHover(null)}>
                {ticks.map(t => <div key={t} className="pointer-events-none absolute inset-x-0 border-t border-data-grid" style={{ top: `${(1 - t / top) * 100}%` }} />)}
                <div className="absolute inset-0 flex items-end">
                  {points.map((p, i) => (
                    <div key={p.day} className="flex h-full flex-1 items-end" onPointerEnter={() => setHover(i)}>
                      <div
                        className="ds-bar mx-auto w-[70%] rounded-t-ds-sm bg-data-3 data-lit:bg-data-1"
                        data-lit={hover === i || (hover === null && (!focus || focus.includes(i))) || undefined}
                        style={{ height: p.value > 0 ? `max(2px, ${(p.value / top) * 100}%)` : '0', '--i': (i * 120) / points.length } as CSSProperties}
                      />
                    </div>
                  ))}
                </div>
              </div>
              <div />
              <div className="relative mt-2 h-4" aria-hidden="true">
                {marks.map((m, i) => (
                  <span
                    key={m.text}
                    className={cn('absolute whitespace-nowrap type-caption text-fg-muted tabular-nums', i === 0 ? 'left-0' : i === marks.length - 1 ? 'right-0' : '-translate-x-1/2')}
                    style={i === 0 || i === marks.length - 1 ? {} : { left: m.left }}
                  >{m.text}</span>
                ))}
              </div>
            </div>
          )}
    </figure>
  )
}

export default BarChart

const css = `
.ds-bar { transform-origin: bottom; animation: ds-bar-in var(--ds-duration-entrance) var(--ds-easing-out) both; animation-delay: calc(var(--i, 0) * 1ms); transition: background-color var(--ds-duration-glide) var(--ds-easing-standard); }
@keyframes ds-bar-in { from { transform: scaleY(0.02); } }
@media (prefers-reduced-motion: reduce) { .ds-bar { animation: none; } }
`

'use client'
import { useState, type PointerEvent } from 'react'
import { type LineSeries, PLOT, compactNumber, lineLayout } from '@/lib/chart'
import { cn } from '@/react/lib/cn'

// Lines over time: one axis from 0 on #363636 hairlines, 2px lines in the brand's series order (White, #A3A3A3,
// #4D4D4D dashed, then the spectrum: Magenta, Red, Orange, Yellow, Green, Cyan, Blue), the first series shading the
// area under it, a legend when there is more than one, and a crosshair with the values under the pointer on the
// #262626 overlay panel. Ten series at most. On a #262626 card by default; `bare` drops the card, for a chart already
// inside one. `format` writes a value (axis figures use the compact form unless `formatAxis` is given).
export type { LineSeries }

export interface LineChartProps {
  /** The caption: what the lines count. */
  title: string
  /** [{ label, points: [{ t (ms), v }] }], ten at most. */
  series: LineSeries[]
  /** A value as written in the crosshair. */
  format?: (value: number) => string
  /** An axis figure as written. */
  formatAxis?: (value: number) => string
  /** How a time reads under the plot and in the crosshair. */
  formatTime?: (t: number) => string
  /** No card, inside one already. */
  bare?: boolean
}

const day = (t: number) => new Date(t).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' })

export function LineChart({ title, series, format = String, formatAxis = compactNumber, formatTime = day, bare }: LineChartProps) {
  const { lines, paths, span, ticks, max, x, nearest, valuesAt } = lineLayout(series)
  const [hover, setHover] = useState<number | null>(null)
  function move(event: PointerEvent<HTMLDivElement>) {
    const box = event.currentTarget.getBoundingClientRect()
    setHover(nearest((event.clientX - box.left) / box.width))
  }
  const hovered = hover === null ? null : { left: `${(x(hover) / PLOT.w) * 100}%`, right: x(hover) > PLOT.w * 0.6, time: formatTime(hover), values: valuesAt(hover) }

  return (
    <figure data-ds="line-chart" className={cn('flex min-w-0 flex-col gap-4', !bare && 'rounded-container bg-surface-raised p-6 max-sm:p-4')}>
      <figcaption className="flex min-h-5 flex-wrap items-baseline justify-between gap-x-4 gap-y-2">
        <span className="type-label text-fg-muted">{title}</span>
        {lines.length > 1 && (
          <span className="flex flex-wrap gap-x-4 gap-y-1 type-caption text-fg-muted">
            {paths.map(p => (
              <span key={p.label} className="inline-flex items-center gap-1.5">
                <svg width="16" height="4" aria-hidden="true"><line x1="0" y1="2" x2="16" y2="2" stroke={p.color} strokeWidth="2" strokeDasharray={p.dash || undefined} /></svg>
                {p.label}
              </span>
            ))}
          </span>
        )}
      </figcaption>
      {!lines.length
        ? <p className="type-ui text-fg-muted">No data in this range.</p>
        : (
            <div className="flex gap-2">
              <div className="relative h-40 w-10 shrink-0" aria-hidden="true">
                {ticks.map(t => <span key={t} className="absolute right-0 -translate-y-1/2 whitespace-nowrap type-caption text-fg-muted tabular-nums" style={{ top: `${(1 - t / max) * 100}%` }}>{formatAxis(t)}</span>)}
              </div>
              <div className="min-w-0 flex-1">
                <div className="relative h-40 touch-none" role="img" aria-label={`${title}: ${paths.map(p => `${p.label} last ${format(p.last.v)}`).join(', ')}`} onPointerMove={move} onPointerLeave={() => setHover(null)}>
                  <svg className="absolute inset-0 h-full w-full overflow-visible" viewBox={`0 0 ${PLOT.w} ${PLOT.h}`} preserveAspectRatio="none" aria-hidden="true">
                    {ticks.map(t => <line key={t} x1="0" y1={PLOT.h - (t / max) * PLOT.h} x2={PLOT.w} y2={PLOT.h - (t / max) * PLOT.h} stroke="var(--ds-color-data-grid)" strokeWidth="1" vectorEffect="non-scaling-stroke" />)}
                    {paths.filter(q => q.area).map(p => <path key={`${p.label}-area`} d={p.area} fill={p.color} fillOpacity="0.08" />)}
                    {paths.map(p => <path key={p.label} d={p.d} fill="none" stroke={p.color} strokeWidth="2" strokeDasharray={p.dash || undefined} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />)}
                  </svg>
                  {hovered && (
                    <>
                      <div className="pointer-events-none absolute inset-y-0 w-px bg-edge-strong" style={{ left: hovered.left }} />
                      <div className="pointer-events-none absolute top-0 z-10 flex flex-col gap-1 rounded-control border border-edge bg-surface-raised px-3 py-2 type-caption" style={hovered.right ? { right: `calc(100% - ${hovered.left} + 8px)` } : { left: `calc(${hovered.left} + 8px)` }}>
                        <p className="text-fg-muted tabular-nums">{hovered.time}</p>
                        {hovered.values.map(v => (
                          <p key={v.label} className="flex items-center gap-2 whitespace-nowrap tabular-nums">
                            <span className="inline-block h-0.5 w-3" style={{ background: v.color }} />
                            {lines.length > 1 && <span className="text-fg-muted">{v.label}</span>}
                            <span className="ml-auto font-medium text-fg">{v.value === undefined ? 'None' : format(v.value)}</span>
                          </p>
                        ))}
                      </div>
                    </>
                  )}
                </div>
                <div className="mt-2 flex justify-between type-caption text-fg-muted tabular-nums">
                  <span>{formatTime(span.from)}</span>
                  <span>{formatTime(span.to)}</span>
                </div>
              </div>
            </div>
          )}
    </figure>
  )
}

export default LineChart

// What the charts share, in both flavors: the series colors, numbers in en-US, an axis that ends on a round number in
// about four steps, and the days under the bars. Framework-free.

/**
 * The series colors in order: the neutrals first (White, #A3A3A3, #4D4D4D), then the spectrum in the order the brand
 * always shows it (Magenta, Red, Orange, Yellow, Green, Cyan, Blue). Ten series at most; the third is dashed, so a
 * dim gray line still reads, and every series is named in the legend.
 */
export const CHART_COLORS = [
	'var(--ds-color-data-1)',
	'var(--ds-color-data-2)',
	'var(--ds-color-data-3)',
	'var(--ds-color-magenta)',
	'var(--ds-color-red)',
	'var(--ds-color-orange)',
	'var(--ds-color-yellow)',
	'var(--ds-color-green)',
	'var(--ds-color-cyan)',
	'var(--ds-color-blue)',
] as const
/** Each series' dash pattern (SVG stroke-dasharray), by the same index. */
export const CHART_DASH = ['', '', '5 4', '', '', '', '', '', '', '']

export type DayPoint = { day: string, value: number }
export type LineSeries = { label: string, points: Array<{ t: number, v: number }> }

const whole = new Intl.NumberFormat('en-US')
const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })

/** 186402 -> "186,402". */
export const formatNumber = (n: number) => whole.format(n)
/** 186402 -> "186.4K", for axis labels. */
export const compactNumber = (n: number) => compact.format(n)

/** The axis: a step of 1, 2, 2.5 or 5 times a power of ten that covers the largest value in four. Starts at 0. */
export function niceTicks(values: number[]) {
	const max = Math.max(0, ...values)
	if (max === 0) return [0, 1]
	const raw = max / 4
	const power = 10 ** Math.floor(Math.log10(raw))
	const step = ([1, 2, 2.5, 5, 10].find((m) => m * power >= raw) ?? 10) * power
	return Array.from({ length: Math.ceil(max / step) + 1 }, (_, i) => i * step)
}

/** "Oct 2", or "Oct 2, 2026" with the year, from an ISO day. */
export const formatDay = (value: string, year = false) => new Date(`${value}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', ...(year ? { year: 'numeric' } : {}), timeZone: 'UTC' })

/** Four dates under n bars: the first, the last and two between, each with its center as a share of the width. */
export function dayMarks(points: DayPoint[]) {
	const n = points.length
	if (!n) return []
	return [...new Set([0, Math.round((n - 1) / 3), Math.round((2 * (n - 1)) / 3), n - 1])].map((i) => ({ left: `${((i + 0.5) / n) * 100}%`, text: formatDay(points[i]!.day) }))
}

/** The plot's drawing box for lines (an SVG viewBox, stretched to the plot). */
export const PLOT = { w: 600, h: 160 }

/** Lines over time laid out in PLOT: paths, the shaded area under the first, the axis top and the hovered values. */
export function lineLayout(series: LineSeries[]) {
	const lines = series.slice(0, CHART_COLORS.length).filter((s) => s.points.length)
	const times = [...new Set(lines.flatMap((s) => s.points.map((p) => p.t)))].sort((a, b) => a - b)
	const span = { from: times[0] ?? 0, to: times[times.length - 1] ?? 1 }
	const ticks = niceTicks(lines.flatMap((s) => s.points.map((p) => p.v)))
	const max = ticks[ticks.length - 1]!
	const x = (t: number) => (span.to === span.from ? PLOT.w / 2 : ((t - span.from) / (span.to - span.from)) * PLOT.w)
	const y = (v: number) => PLOT.h - (v / max) * PLOT.h
	const paths = lines.map((s, i) => ({
		label: s.label,
		color: CHART_COLORS[i]!,
		dash: CHART_DASH[i]!,
		d: s.points.map((p, j) => `${j ? 'L' : 'M'}${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join(''),
		area: i ? '' : `M${x(s.points[0]!.t).toFixed(1)},${PLOT.h}${s.points.map((p) => `L${x(p.t).toFixed(1)},${y(p.v).toFixed(1)}`).join('')}L${x(s.points[s.points.length - 1]!.t).toFixed(1)},${PLOT.h}Z`,
		last: s.points[s.points.length - 1]!,
	}))
	/** The time nearest a share (0 to 1) of the width. */
	const nearest = (share: number) => {
		const t = span.from + share * (span.to - span.from)
		let best: number | null = null
		for (const c of times) if (best === null || Math.abs(c - t) < Math.abs(best - t)) best = c
		return best
	}
	const valuesAt = (t: number) => lines.map((s, i) => ({ label: s.label, color: CHART_COLORS[i]!, value: s.points.find((p) => p.t === t)?.v }))
	return { lines, paths, span, ticks, max, x, nearest, valuesAt }
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

