import { BarChart } from '@/react/components/ui/BarChart'
import { formatNumber, type DayPoint } from '@/lib/chart'
// A month of searches on a #262626 card: the total in Funnel Display, the bars per day under it. Point at a bar to
// read it. Sample data.
const days = Array.from({ length: 30 }, (_, i) => `2026-10-${String(i + 2).padStart(2, '0')}`)
const points: DayPoint[] = days.map((day, i) => ({ day, value: Math.round(1800 * (0.2 + (((i * 7) % 23) / 23) ** 2 * 0.8)) }))
const total = points.reduce((a, p) => a + p.value, 0)

export default function Searches() {
  return (
    <div className="flex w-full max-w-150 flex-col gap-6 rounded-container bg-surface-raised p-6 max-sm:p-4">
      <div className="flex flex-col gap-2">
        <p className="type-label text-fg-muted">Searches, October</p>
        <p className="type-heading-1 tabular-nums">{formatNumber(total)}</p>
      </div>
      <BarChart points={points} label="Searches per day" height={140} />
    </div>
  )
}

'use client'
import { LineChart, type LineSeries } from '@/react/components/ui/LineChart'
// New creatives found per day by category over two weeks: six series in the brand's order, the neutrals first, then
// the spectrum. Point at the plot to read a day. Sample data.
const day = (i: number) => Date.UTC(2026, 10, 2 + i)
const categories = ['Skincare', 'Snacks', 'Fitness', 'Beverages', 'Apparel', 'Home']
const series: LineSeries[] = categories.map((label, k) => ({
  label,
  points: Array.from({ length: 14 }, (_, i) => ({ t: day(i), v: Math.round(120 - k * 16 + ((i * (k + 3) * 7) % 11) * 4 + i * (3 - k * 0.4)) })),
}))
const count = (v: number) => `${Math.round(v)} creatives`

export default function Categories() {
  return (
    <div className="w-full max-w-238">
      <LineChart title="New creatives per day" series={series} format={count} />
    </div>
  )
}

